    (1998, "عَاجِلًا يَعُودُ الْمُسَافِرُ إِلَى بَيْتِهِ.", "Bald kehrt der Reisende in sein Haus zurück.", [("عَاجِلًا", "bald"), ("يَعُودُ", "kehrt zurück"), ("الْمُسَافِرُ", "der Reisende"), ("إِلَى", "in"), ("بَيْتِهِ", "sein Haus")]),
    (1999, "أَثْنَاءَ الْعَمَلِ جَلَسَ الْمُوَظَّفُ فِي مَكْتَبِهِ.", "Während der Arbeit saß der Angestellte in seinem Büro.", [("أَثْنَاءَ", "während"), ("الْعَمَلِ", "der Arbeit"), ("جَلَسَ", "saß"), ("الْمُوَظَّفُ", "der Angestellte"), ("فِي", "in"), ("مَكْتَبِهِ", "seinem Büro")]),
    (1999, "أَثْنَاءَ الْحِوَارِ فَهِمَ الْجَمِيعُ الْفِكْرَةَ.", "Während des Gesprächs verstanden alle die Idee.", [("أَثْنَاءَ", "während"), ("الْحِوَارِ", "des Gesprächs"), ("فَهِمَ", "verstanden"), ("الْجَمِيعُ", "alle"), ("الْفِكْرَةَ", "die Idee")]),
